    int height;         // 키(cm) · 강의는 float
} person;
int main(void)
{
    person a = { {{x}}, {{y}} }, b;
    b = a;                  // 가능
    a.age = a.age + 1;      // a만 바꾸면?
    if( a.age > b.age )     // 필드를 골라 비교
        printf("a가 b보다 나이가 많음");
