#include <stddef.h>
typedef struct ListNode {
    int data;               // 강의는 char data[10]
    struct ListNode *link;
} ListNode;
int main(void)
{
    ListNode n2 = { {{y}}, NULL };
    ListNode n1 = { {{x}}, &n2 };
    ListNode c;
    c = n1;                 // 필드별 복사
    c.data = c.data + 1;    // c만 바뀜
    c.link->data = 0;       // n2를 바꿈
    int seen = n1.link->data;   // n1에서 보면?
    return 0;
}
